
"use client";

import { useState, type FormEvent } from "react";
import {
  ArrowRight,
  Eye,
  EyeOff,
  LockKeyhole,
  Mail,
  MessageCircle,
} from "lucide-react";

export default function HomePage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");
    setLoading(true);

    try {
      // TODO: Call your authentication API here.
      // Redirect to /c/me after successful authentication.
      setError("Authentication is not configured yet.");
    } catch {
      setError("Sign in failed. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="flex min-h-dvh items-center justify-center bg-[#F3F7FA] px-4 py-8">
      <div className="w-full max-w-[420px]">
        {/* Branding */}
        <div className="mb-9 flex flex-col items-center">
          <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[#02394F] shadow-sm">
            <MessageSquareText
              size={28}
              strokeWidth={1.8}
              className="text-white"
            />
          </div>

          <h1 className="mt-5 text-2xl font-bold tracking-tight text-[#02394F] sm:text-[28px]">
            Messenger AI
          </h1>

          <div className="mt-3 h-1 w-10 rounded-full bg-[#008EED]" />
        </div>

        {/* Login card */}
        <section className="rounded-2xl border border-[#E2EAF0] bg-white p-6 shadow-[0_8px_35px_rgba(2,57,79,0.05)] sm:p-9">
          <h2 className="text-xl font-semibold text-[#02394F]">
            Sign in
          </h2>

          <form onSubmit={handleSubmit} className="mt-7 space-y-5">
            <div>
              <label
                htmlFor="email"
                className="mb-2 block text-sm font-medium text-[#344D5B]"
              >
                Email
              </label>

              <div className="relative">
                <Mail
                  size={18}
                  className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-[#8296A5]"
                />

                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  placeholder="Enter your email"
                  autoComplete="email"
                  required
                  className="h-12 w-full rounded-lg border border-[#DCE5EC] bg-white pl-11 pr-4 text-sm text-[#02394F] outline-none transition-colors placeholder:text-[#9AAAB5] focus:border-[#008EED] focus:ring-2 focus:ring-[#008EED]/10"
                />
              </div>
            </div>

            <div>
              <label
                htmlFor="password"
                className="mb-2 block text-sm font-medium text-[#344D5B]"
              >
                Password
              </label>

              <div className="relative">
                <LockKeyRound
                  size={18}
                  className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-[#8296A5]"
                />

                <input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={(event) => setPassword(event.target.value)}
                  placeholder="Enter your password"
                  autoComplete="current-password"
                  required
                  className="h-12 w-full rounded-lg border border-[#DCE5EC] bg-white pl-11 pr-11 text-sm text-[#02394F] outline-none transition-colors placeholder:text-[#9AAAB5] focus:border-[#008EED] focus:ring-2 focus:ring-[#008EED]/10"
                />

                <button
                  type="button"
                  onClick={() => setShowPassword((value) => !value)}
                  aria-label={
                    showPassword ? "Hide password" : "Show password"
                  }
                  className="absolute right-3 top-1/2 flex h-7 w-7 -translate-y-1/2 items-center justify-center text-[#8296A5] hover:text-[#008EED]"
                >
                  {showPassword ? (
                    <EyeOff size={18} />
                  ) : (
                    <Eye size={18} />
                  )}
                </button>
              </div>
            </div>

            {error && (
              <p role="alert" className="text-sm text-red-600">
                {error}
              </p>
            )}

            <button
              type="submit"
              disabled={loading}
              className="flex h-12 w-full items-center justify-center gap-2 rounded-lg bg-[#008EED] text-sm font-semibold text-white transition-colors hover:bg-[#007ACD] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#008EED] disabled:cursor-not-allowed disabled:opacity-60"
            >
              {loading ? "Signing in..." : "Sign in"}
              {!loading && <ArrowRight size={18} />}
            </button>
          </form>
        </section>

        <p className="mt-6 text-center text-xs text-[#8296A5]">
          Staffgate · Internal access
        </p>
      </div>
    </main>
  );
}